use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::{Path,PathBuf},process::{Command,Stdio}};
const R:&str="/home/ubuntu/src/zopro-perf-work/g1-control-codegen176";
const P:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-06-g1-control-codegen176";
fn h(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn walk(p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();assert!(!e.file_type().unwrap().is_symlink());if e.file_type().unwrap().is_dir(){walk(&e.path(),out)}else{out.push(e.path())}}}
fn main(){assert!(!Path::new(P).exists());let mut pin_occurrences=0;let mut commands=0;for(prefix,dir)in[("","workflow"),("compare-","compare-workflow"),("helper-","helper-workflow"),("scalar-","scalar-workflow")]{let pins=read(format!("{R}/{prefix}pins.json"));for(p,sha)in pins.as_object().unwrap(){assert_eq!(h(&fs::read(p).unwrap()),sha.as_str().unwrap());pin_occurrences+=1}let plan=read(format!("{R}/{prefix}plan.json"));assert_eq!(read(format!("{R}/{dir}/result.json"))["status"],"complete");for step in plan["steps"].as_array().unwrap(){let d=format!("{R}/{dir}/{}",step["name"].as_str().unwrap());let c=read(format!("{d}/command.json"));assert_eq!(&c["argv"].as_array().unwrap()[4..],step["argv"].as_array().unwrap());let e=read(format!("{d}/exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for stream in["stdout","stderr"]{assert_eq!(h(&fs::read(format!("{d}/{stream}.log")).unwrap()),e[format!("{stream}_sha256")].as_str().unwrap());}commands+=1}}
assert_eq!(commands,4);assert_eq!(pin_occurrences,54);let mut sites=0;let mut loads=0;let mut addresses=0;for file in["comparison.json","helper-comparison.json","scalar-comparison.json"]{let v=read(format!("{R}/{file}"));for(k,row)in v["rows"].as_object().unwrap(){assert!(row["unresolved_RIP"].as_array().unwrap().is_empty());if k.starts_with("original"){sites+=row["lines"].as_array().unwrap().len();for r in row["RIP_references"].as_array().unwrap(){if r["kind"]=="constant_load"{loads+=1}else{addresses+=1}}}}for c in v["comparisons"].as_object().unwrap().values(){let equal=c.get("all_normalized_instructions_equal").or_else(||c.get("normalized_equal")).unwrap();assert_eq!(equal,true)}}assert_eq!((sites,loads,addresses),(8009,110,29));
let manifest=read("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json");for(p,sha)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(h(&fs::read(format!("/home/ubuntu/src/zk-tools/zopro/{p}")).unwrap()),sha.as_str().unwrap());}let ledger=read("/home/ubuntu/src/zopro-perf-work/coarse-proof-phase-universal176/proof-sha256-after.json");assert_eq!(ledger.as_array().unwrap().len(),30846);
let summary=json!({"workflow_commands":commands,"pin_occurrences_verified":pin_occurrences,"functions_per_build":4,"instruction_rows_per_build":sites,"constant_load_sites_per_build":loads,"address_only_sites_per_build":addresses,"all_normalized_instructions_and_loaded_constants_equal":true,"unresolved_RIP_operands":0,"external_address_objects_and_allocator_panic_bodies_not_semantically_compared":true,"separate_semantic_reviewer":false,"cause_of_prior_control_shift_established":false,"new_runtime_candidate":false,"new_timing_profile_proof_or_native_test":false,"source176_unchanged":true,"proof_ledger":30846,"accepted_1x2_ms":7.928660,"all8_CPU10x_rows":0,"goal_status":"active/unmet"});fs::write(format!("{R}/summary.json"),serde_json::to_vec_pretty(&summary).unwrap()).unwrap();
let a=Path::new(P).join("artifacts");fs::create_dir_all(&a).unwrap();let mut paths=vec![];walk(Path::new(R),&mut paths);paths.sort();let mut archive=BTreeMap::new();for path in paths{let name=path.file_name().unwrap().to_string_lossy();if name.starts_with("checkpoint"){continue}let ext=path.extension().and_then(|s|s.to_str());if !matches!(ext,Some("rs"|"json"|"md"|"txt"|"stdout"|"stderr"|"log")){continue}let b=fs::read(&path).unwrap();let text=String::from_utf8(b.clone()).unwrap();assert_eq!(text.as_bytes(),b);archive.insert(path.strip_prefix(R).unwrap().to_string_lossy().to_string(),json!({"bytes":b.len(),"sha256":h(&b),"utf8":text}));}
let bytes=serde_json::to_vec(&archive).unwrap();for v in archive.values(){assert_eq!(v["utf8"].as_str().unwrap().len(),v["bytes"].as_u64().unwrap()as usize);assert_eq!(h(v["utf8"].as_str().unwrap().as_bytes()),v["sha256"])}let temp=a.join("archive.tmp");fs::write(&temp,&bytes).unwrap();let gz=a.join("source-and-receipts.json.gz");assert!(Command::new("gzip").args(["-n","-c"]).arg(&temp).stdout(Stdio::from(fs::File::create(&gz).unwrap())).status().unwrap().success());let back=Command::new("gzip").args(["-d","-c"]).arg(&gz).output().unwrap();assert!(back.status.success());assert_eq!(back.stdout,bytes);fs::remove_file(temp).unwrap();
for file in["extract.rs","compare.rs","prepare-helpers.rs","prepare-scalar.rs","publish.rs","summary.json","design.md"]{let b=fs::read(format!("{R}/{file}")).unwrap();fs::write(a.join(file),&b).unwrap();assert_eq!(fs::read(a.join(file)).unwrap(),b)}fs::copy(format!("{R}/report-draft.md"),Path::new(P).join("README.md")).unwrap();let publication=json!({"UTF8_source_receipt_members":archive.len(),"all_member_hashes_and_roundtrip_verified":true,"archive_uncompressed_sha256":h(&bytes),"runtime_arrays_or_executables_included":false});fs::write(a.join("publication.json"),serde_json::to_vec_pretty(&publication).unwrap()).unwrap();let mut files=vec![];walk(Path::new(P),&mut files);files.sort();let mut sums=String::new();for p in &files{sums.push_str(&format!("{}  {}\n",h(&fs::read(p).unwrap()),p.strip_prefix(P).unwrap().display()));}fs::write(Path::new(P).join("SHA256SUMS"),sums).unwrap();println!("Published {}files/{}UTF8members/54pins/4workflows; all rounds and hashes pass; no new performance",files.len()+1,archive.len());}
